                session.setAttribute("foo", output);
            } else {
                output = (String) session.getAttribute("foo");
                if (output != null) {
                    output = "old";
                }
            }
            PrintWriter out = response.getWriter();
            out.write(output);
        }
    };
    tester.setAttribute("callback_1", c);
