/**
 * Test that we don't leave native sessions in the container, wasting memory
 */
@Test
public void shouldNotLeaveNativeSessionInContainer() throws IOException, URISyntaxException, InterruptedException {
    manager.startAllInactiveContainers();
    String key = "value_testSessionExpiration";
    String value = "Foo";
    client.setPort(Integer.parseInt(manager.getContainerPort(0)));
    Client.Response resp = client.set(key, value);
    String cookie = resp.getSessionCookie();
    for (int i = 0; i < manager.numContainers(); i++) {
        client.setPort(Integer.parseInt(manager.getContainerPort(i)));
        resp = client.get(key);
        assertEquals("Sessions are not replicating properly", cookie, resp.getSessionCookie());
        assertEquals(value, resp.getResponse());
    }
    for (int i = 0; i < manager.numContainers(); i++) {
        client.setPort(Integer.parseInt(manager.getContainerPort(i)));
        resp = client.executionFunction(GetSessionCount.class);
        assertEquals("Should have 0 native sessions", "0", resp.getResponse());
    }
}

/**
 * Test that we cache the user's session on the client, rather than going to the server for each
 * request
 */
@Test
public void shouldCacheSessionOnClient() throws IOException, URISyntaxException, InterruptedException {
    manager.startAllInactiveContainers();
    String key = "value_testSessionExpiration";
    String value = "Foo";
    client.setPort(Integer.parseInt(manager.getContainerPort(0)));
    Client.Response resp = client.set(key, value);
    String cookie = resp.getSessionCookie();
    // Modify the values on the server
    serverVM.invoke(() -> {
        Cache cache = getCache();
        Region<String, HttpSession> region = cache.getRegion("gemfire_modules_sessions");
        region.values().forEach(session -> session.setAttribute(key, "bogus"));
    });
    // Make sure the client still sees it's original cached value
    resp = client.get(key);
    assertEquals(value, resp.getResponse());
}

