            long remaining = TIMEOUT;
            while (factory.finds < 2 && remaining > 0) {
                factory.wait(remaining);
                remaining = TIMEOUT - (System.currentTimeMillis() - start);
            }
        }
        long end = System.currentTimeMillis();
