@Test
public void testPRQueryForDuplicates() throws CacheException {
    final String regionName = "exampleRegion";
    final Host host = Host.getHost(0);
    final VM vm0 = host.getVM(0);
    final VM vm1 = host.getVM(1);
    final VM vm2 = host.getVM(2);
    final String name = "/" + regionName;
    final String[] qs = { "select distinct pkid from " + name, "select distinct pkid, status from " + name };
    // Start server1
    final int port1 = (Integer) vm0.invoke(new SerializableCallable("Create Server1") {

        @Override
        public Object call() throws Exception {
            Region r1 = getCache().createRegionFactory(RegionShortcut.PARTITION).create(regionName);
            CacheServer server = getCache().addCacheServer();
            int port = AvailablePortHelper.getRandomAvailablePortForDUnitSite();
            server.setPort(port);
            server.start();
            return port;
        }
    });
    // Start server2
    final int port2 = (Integer) vm1.invoke(new SerializableCallable("Create Server1") {

        @Override
        public Object call() throws Exception {
            Region r1 = getCache().createRegionFactory(RegionShortcut.PARTITION).create(regionName);
            CacheServer server = getCache().addCacheServer();
            int port = AvailablePortHelper.getRandomAvailablePortForDUnitSite();
            server.setPort(port);
            server.start();
            return port;
        }
    });
    // create client load data and execute queries
    vm2.invoke(new SerializableCallable("Create client") {

        @Override
        public Object call() throws Exception {
            ClientCacheFactory cf = new ClientCacheFactory();
            cf.addPoolServer(NetworkUtils.getServerHostName(vm0.getHost()), port1);
            cf.addPoolServer(NetworkUtils.getServerHostName(vm1.getHost()), port2);
            ClientCache cache = getClientCache(cf);
            Region region = cache.createClientRegionFactory(ClientRegionShortcut.PROXY).create(regionName);
            // Put Portfolios with 2 different pkids
            for (int set = 1; set <= 2; set++) {
                for (int current = 1; current <= 5; current++) {
                    region.put("key-" + set + "_" + current, new PortfolioPdx(set, current));
                }
            }
            for (int i = 0; i < qs.length; i++) {
                SelectResults sr = (SelectResults) cache.getQueryService().newQuery(qs[i]).execute();
                assertEquals("Did not get expected result from query: " + qs[i] + " ", 2, sr.size());
            }
            return null;
        }
    });
    // execute query on server by setting DefaultQuery.setPdxReadSerialized
    // to simulate remote query
    vm0.invoke(new SerializableCallable("Create server") {

        @Override
        public Object call() throws Exception {
            DefaultQuery.setPdxReadSerialized(true);
            try {
                for (int i = 0; i < qs.length; i++) {
                    SelectResults sr = (SelectResults) getCache().getQueryService().newQuery(qs[i]).execute();
                    assertEquals("Did not get expected result from query: " + qs[i] + " ", 2, sr.size());
                }
            } finally {
                DefaultQuery.setPdxReadSerialized(false);
            }
            return null;
        }
    });
    disconnectAllFromDS();
}

@Test
public void testCompactRangeIndex() {
    // Create caches
    Properties props = new Properties();
    server.invoke(() -> PRClientServerTestBase.createCacheInVm(props));
    server.invoke(new CacheSerializableRunnable("create indexes") {

        @Override
        public void run2() throws CacheException {
            cache = CacheFactory.getAnyInstance();
            Region region = cache.createRegionFactory(RegionShortcut.REPLICATE).create(repRegionName);
            // Create common Portflios and NewPortfolios
            for (int j = cnt; j < cntDest; j++) {
                region.put(new Integer(j), new Portfolio(j));
            }
            QueryService qs = CacheFactory.getAnyInstance().getQueryService();
            try {
                Index index = qs.createIndex("idIndex", "ID", "/" + repRegionName);
                assertEquals(10, index.getStatistics().getNumberOfKeys());
            } catch (Exception e) {
                fail("Index creation failed");
            }
        }
    });
    // Invoke update from client and stop in updateIndex
    // first before updating the RegionEntry and second after updating
    // the RegionEntry.
    AsyncInvocation putThread = server.invokeAsync(new CacheSerializableRunnable("update a Region Entry") {

        @Override
        public void run2() throws CacheException {
            Region repRegion = CacheFactory.getAnyInstance().getRegion(repRegionName);
            IndexManager.testHook = new IndexManagerTestHook();
            repRegion.put(new Integer("1"), new Portfolio(cntDest + 1));
            // above call must be hooked in BEFORE_UPDATE_OP call.
        }
    });
    server.invoke(new CacheSerializableRunnable("query on server") {

        @Override
        public void run2() throws CacheException {
            QueryService qs = CacheFactory.getAnyInstance().getQueryService();
            while (!hooked) {
                Wait.pause(100);
            }
            Object rs = null;
            try {
                rs = qs.newQuery("<trace> select * from /" + repRegionName + " where ID = 1").execute();
            } catch (Exception e) {
                e.printStackTrace();
                fail("Query execution failed on server.");
                IndexManager.testHook = null;
            }
            assertTrue(rs instanceof SelectResults);
            assertEquals(1, ((SelectResults) rs).size());
            Portfolio p1 = (Portfolio) ((SelectResults) rs).asList().get(0);
            if (p1.getID() != 1) {
                fail("Query thread did not verify index results even when RE is under update");
                IndexManager.testHook = null;
            }
            // Let client put go further.
            hooked = false;
        }
    });
    // Client put is again hooked in AFTER_UPDATE_OP call in updateIndex.
    server.invoke(new CacheSerializableRunnable("query on server") {

        @Override
        public void run2() throws CacheException {
            QueryService qs = CacheFactory.getAnyInstance().getQueryService();
            while (!hooked) {
                Wait.pause(100);
            }
            Object rs = null;
            try {
                rs = qs.newQuery("<trace> select * from /" + repRegionName + " where ID = 1").execute();
            } catch (Exception e) {
                e.printStackTrace();
                fail("Query execution failed on server." + e.getMessage());
            } finally {
                IndexManager.testHook = null;
            }
            assertTrue(rs instanceof SelectResults);
            if (((SelectResults) rs).size() > 0) {
                Portfolio p1 = (Portfolio) ((SelectResults) rs).iterator().next();
                if (p1.getID() != 1) {
                    fail("Query thread did not verify index results even when RE is under update and " + "RegionEntry value has been modified before releasing the lock");
                    IndexManager.testHook = null;
