                    fail(" Value of ID is not as expected, it is: " + id + " expected :" + i);
                }
            } else {
                if (!pkid.equals("" + i)) {
                    fail(" Value of pkid is not as expected, " + pkid);
                }
                if (id != i) {
                    fail(" Value of ID is not as expected, " + id);
                }
            }
        }
        // Query 11 - ID desc, pkid field values should be in the same order.
