                    }
                    break;
                case 2:
                    if (ct.getElementType().getSimpleClassName().equals("Struct")) {
                        assertTrue(true);
                    } else {
                        System.out.println("StructMemberAcessJUnitTest::testResultComposition:Colelction Element's class=" + ct.getElementType().getSimpleClassName());
                        fail();
                    }
            }
        }
    }
}

