        }
    }
}

@Test
public void testIndexUseMultipleConditions() throws Exception {
    String[][] testData = { { "P1.secType = 'a'", "0" }, { "status = 'active' AND ID = 2", "1" }, { "status = 'active' AND ID = 2 AND P1.secId  = 'IBM'", "1" }, { "status = 'active' OR ID = 2", "2" }, { "status = 'active' OR ID = 2 OR P1.secId  = 'IBM'", "3" }, { "status = 'active' AND ID = 2 OR P1.secId  = 'IBM'", "2" }, { "status = 'active' AND ( ID = 2 OR P1.secId  = 'IBM')", "1" }, { "status = 'active' OR ID = 2 AND P1.secId  = 'IBM'", "2" }, { "(status = 'active' OR ID = 2) AND P1.secId  = 'IBM'", "1" }, { "NOT (status = 'active') AND ID = 2", "1" }, { "status = 'active' AND NOT( ID = 2 )", "1" }, { "NOT (status = 'active') OR ID = 2", "2" }, { "status = 'active' OR NOT( ID = 2 )", "2" }, { "status = 'active' AND P1.secType = 'a'", "1" }, { "status = 'active' OR P1.secType = 'a'", "0" }, { "status = 'active' AND ID =1 AND P1.secType = 'a'", "1" }, { "status = 'active' AND ID = 1 OR P1.secType = 'a'", "0" }, { "status = 'active' OR ID = 1 AND P1.secType = 'a'", "2" }, { "P2.secId = null", "1" }, { "IS_UNDEFINED(P2.secId)", "1" }, { "IS_DEFINED(P2.secId)", "1" }, { "P2.secId = UNDEFINED", "0" } };
    for (int j = 0; j < testData.length; j++) {
        Query q = qs.newQuery("SELECT DISTINCT * FROM /pos where " + testData[j][0]);
        QueryObserverImpl observer = new QueryObserverImpl();
        QueryObserverHolder.setInstance(observer);
        q.execute();
        if (observer.indexesUsed.size() != Integer.parseInt(testData[j][1])) {
            fail("Wrong Index use for " + testData[j][0] + "\n Indexes used " + observer.indexesUsed);
        }
    }
}

