                CacheUtils.getLogger().info("index p: " + p);
                if (i == 0) {
                    assertEquals(p.getID(), 10);
                    assertEquals(p.pkid, "" + (numObjects - 10));
                } else if (i == 1) {
                    assertEquals(p.getID(), 0);
                    assertEquals(p.pkid, "" + numObjects);
                }
            }
            r[i][1] = sr;
