    assertTrue(writer.wasInvoked());
    region.destroy(key);
    assertTrue(writer.wasInvoked());
    region.create(key, value);
    assertTrue(writer.wasInvoked());
    region.destroy(key, arg);
    assertTrue(writer.wasInvoked());
    region.create(key, value);
    assertTrue(writer.wasInvoked());
    try {
        region.destroy(key, exception);
        fail("Should have thrown a CacheWriterException");
    } catch (CacheWriterException ex) {
        // pass...
