 */
@Ignore("TODO")
@Test
public void testBug30705() throws Exception {
    final String name = this.getUniqueName();
    final int numEntries = NUM_ENTRIES_VM;
    final int valueSize = VALUE_SIZE_VM;
    Host host = Host.getHost(0);
    VM vm0 = host.getVM(0);
    VM vm2 = host.getVM(2);
    SerializableRunnable create = new CacheSerializableRunnable("Create Mirrored Region") {

        public void run2() throws CacheException {
            LogWriterUtils.getLogWriter().info("testBug30705: Start creating Mirrored Region");
            AttributesFactory factory = new AttributesFactory(getRegionAttributes());
            factory.setDataPolicy(DataPolicy.REPLICATE);
            createRegion(name, factory.create());
            LogWriterUtils.getLogWriter().info("testBug30705: Finished creating Mirrored Region");
        }
    };
    SerializableRunnable put = new CacheSerializableRunnable("Distributed NoAck Puts") {

        public void run2() throws CacheException {
            Region rgn = getCache().getRegion("/root/" + name);
            assertNotNull(rgn);
            Object key = new Integer(0x42);
            Object value = new byte[0];
            assertNotNull(value);
            LogWriterUtils.getLogWriter().info("testBug30705: Started Distributed NoAck Puts");
            for (int i = 0; i < NUM_PUTS; i++) {
                if (stopPutting) {
                    LogWriterUtils.getLogWriter().info("testBug30705: Interrupted Distributed Ack Puts after " + i + " PUTS");
                    break;
                }
                if ((i % 1000) == 0) {
                    LogWriterUtils.getLogWriter().info("testBug30705: modification #" + i);
                }
                rgn.put(key, value);
            }
        }
    };
    vm0.invoke(create);
    vm0.invoke(new CacheSerializableRunnable("Put data") {

        public void run2() throws CacheException {
            LogWriterUtils.getLogWriter().info("testBug30705: starting initial data load");
            Region region = getRootRegion().getSubregion(name);
            final byte[] value = new byte[valueSize];
            Arrays.fill(value, (byte) 0x42);
            for (int i = 0; i < numEntries; i++) {
                if ((i % 1000) == 0) {
                    LogWriterUtils.getLogWriter().info("testBug30705: initial put #" + i);
                }
                region.put(new Integer(i), value);
            }
            LogWriterUtils.getLogWriter().info("testBug30705: finished initial data load");
        }
    });
    // start putting
    AsyncInvocation async = vm0.invokeAsync(put);
    // do initial image
    try {
        LogWriterUtils.getLogWriter().info("testBug30705: before the critical create");
        vm2.invoke(create);
        LogWriterUtils.getLogWriter().info("testBug30705: after the critical create");
    } finally {
        // test passes if this does not hang
        LogWriterUtils.getLogWriter().info("testBug30705: INTERRUPTING Distributed NoAck Puts after GetInitialImage");
        vm0.invoke(new SerializableRunnable("Interrupt Puts") {

            public void run() {
                LogWriterUtils.getLogWriter().info("testBug30705: interrupting putter");
                stopPutting = true;
            }
        });
        ThreadUtils.join(async, 30 * 1000);
        // wait for overflow queue to quiesce before continuing
        vm2.invoke(new SerializableRunnable("Wait for Overflow Queue") {

            public void run() {
                WaitCriterion ev = new WaitCriterion() {

                    public boolean done() {
                        return getSystem().getDistributionManager().getStats().getOverflowQueueSize() == 0;
                    }

                    public String description() {
                        return "overflow queue remains nonempty";
                    }
                };
                Wait.waitForCriterion(ev, 30 * 1000, 200, true);
            }
        });
    }
    // finally
    LogWriterUtils.getLogWriter().info("testBug30705: at end of test");
    if (async.exceptionOccurred()) {
        Assert.fail("Got exception", async.getException());
    }
}

/**
 * Make sure dynamic regions work on peers
 */
@Test
public void testPeerRegion() {
    assertEquals(true, DynamicRegionFactory.get().isOpen());
    createParentRegion("parent", true);
    Properties p = new Properties();
    doParentCreateOtherVm(p, false);
    Region dr = DynamicRegionFactory.get().createDynamicRegion("parent", "dynamicRegion1");
    String drFullPath = dr.getFullPath();
    dr.put("key1", "value1");
    // test for bug 35528 - support for dynamic subregions of dynamic regions
    for (int i = 0; i < 10; i++) {
        DynamicRegionFactory.get().createDynamicRegion(drFullPath, "subregion" + i);
    }
    LogWriterUtils.getLogWriter().info("testPeerRegion - check #1 make sure other region has new dynamic subregion");
    checkForRegionOtherVm(drFullPath, true);
    // spot check the subregions
    checkForSubregionOtherVm(drFullPath + "/subregion7", true);
    // now see if OTHER can recreate which should fetch meta-info from controller
    recreateOtherVm();
    LogWriterUtils.getLogWriter().info("testPeerRegion - check #2 make sure other region has dynamic region after restarting through getInitialImage");
    checkForRegionOtherVm(drFullPath, true);
    // now close the controller and see if OTHER can still fetch meta-info from disk
    closeCache();
    recreateOtherVm();
    LogWriterUtils.getLogWriter().info("testPeerRegion - check #3 make sure dynamic region can be recovered from disk");
    checkForRegionOtherVm(drFullPath, true);
    for (int i = 0; i < 10; i++) {
        checkForSubregionOtherVm(drFullPath + "/subregion" + i, true);
    }
    // now start our cache back up and see if we still have the dynamic regions
    // even if we don't have disk on the controller to recover from.
    // This means we will get them from the peer
    {
        assertEquals(true, DynamicRegionFactory.get().isClosed());
        DynamicRegionFactory.get().open(new DynamicRegionFactory.Config());
        beginCacheXml();
        createParentRegion("parent", true);
        finishCacheXml("dynamicRegionCTRDUnitTest");
        assertEquals(true, DynamicRegionFactory.get().isOpen());
        assertEquals(true, DynamicRegionFactory.get().isActive());
        Cache c = getCache();
        // verify that controller has all dynamic regions
        assertEquals(true, c.getRegion(drFullPath) != null);
        // now make sure we can destroy dynamic regions
        for (int i = 0; i < 10; i++) {
            String regName = drFullPath + "/subregion" + i;
            assertEquals(true, c.getRegion(regName) != null);
            DynamicRegionFactory.get().destroyDynamicRegion(regName);
            assertEquals(null, c.getRegion(regName));
            checkForSubregionOtherVm(regName, false);
        }
        // make sure that we can explicitly destroy a region and then still
        // ask the factory to destroy it.
        c.getRegion(drFullPath).localDestroyRegion();
        checkForRegionOtherVm(drFullPath, true);
        DynamicRegionFactory.get().destroyDynamicRegion(drFullPath);
        assertEquals(null, c.getRegion(drFullPath));
        checkForRegionOtherVm(drFullPath, false);
    }
}

