                rgn1a.create("key", null);
                rgn2.create("key", null);
                rgn3.create("key", null);
            } catch (CacheException e) {
                Assert.fail("While creating region", e);
            }
        }
    };
    vm0.invoke(createRgn);
    vm1.invoke(createRgn);
    // Standard commit check
    txMgr.begin();
    rgn1.put("key", "value0");
