    for (int vm = 0; vm < numVMs; vm++) {
        final int finalvm = vm;
        Boolean isGrantor = (Boolean) Host.getHost(0).getVM(finalvm).invoke(DistributedLockServiceDUnitTest.class, "isLockGrantor", args);
        if (isGrantor.booleanValue()) {
            originalVM = vm;
            oldGrantor = (InternalDistributedMember) Host.getHost(0).getVM(finalvm).invoke(DistributedLockServiceDUnitTest.class, "identifyLockGrantor", args);
            break;
        }
    }
    LogWriterUtils.getLogWriter().fine("[testBecomeLockGrantor] original grantor is " + oldGrantor);
    // have one call becomeLockGrantor
    for (int vm = 0; vm < numVMs; vm++) {
        if (vm != originalVM) {
            final int finalvm = vm;
            Host.getHost(0).getVM(finalvm).invoke(DistributedLockServiceDUnitTest.class, "becomeLockGrantor", args);
            Boolean isGrantor = (Boolean) Host.getHost(0).getVM(finalvm).invoke(DistributedLockServiceDUnitTest.class, "isLockGrantor", args);
            assertEquals("isLockGrantor is false after calling becomeLockGrantor", Boolean.TRUE, isGrantor);
