        Boolean unlocked = (Boolean) Host.getHost(0).getVM(finalvm).invoke(() -> DistributedLockServiceDUnitTest.unlock(serviceName, "obj-" + finalvm));
        assertEquals("Failed to unlock in testBecomeLockGrantor", Boolean.TRUE, unlocked);
