    AsyncInvocation async1 = lockTheDLocks(vm0, "one", "two");
    AsyncInvocation async2 = lockTheDLocks(vm1, "two", "one");
    Awaitility.await("waiting for locks to be acquired").atMost(60, TimeUnit.SECONDS).until(Awaitility.matches(() -> assertTrue(getBlackboard().isGateSignaled("one"))));
    Awaitility.await("waiting for locks to be acquired").atMost(60, TimeUnit.SECONDS).until(Awaitility.matches(() -> assertTrue(getBlackboard().isGateSignaled("two"))));
    GemFireDeadlockDetector detect = new GemFireDeadlockDetector();
    LinkedList<Dependency> deadlock = detect.find().findCycle();
    assertTrue(deadlock != null);
    System.out.println("Deadlock=" + DeadlockDetector.prettyFormat(deadlock));
    assertEquals(4, deadlock.size());
    disconnectAllFromDS();
    try {
        waitForAsyncInvocation(async1, 45, TimeUnit.SECONDS);
    } finally {
        waitForAsyncInvocation(async2, 45, TimeUnit.SECONDS);
    }
}

/**
 * Test that we can get the value of a thread local from another thread.
 */
@Test
public void test() throws InterruptedException {
    final UnsafeThreadLocal<String> unsafeThreadLocal = new UnsafeThreadLocal<String>();
    final CountDownLatch localSet = new CountDownLatch(1);
    Thread test = new Thread() {

        public void run() {
            unsafeThreadLocal.set("hello");
            localSet.countDown();
            try {
                while (sleep) {
                    Thread.sleep(INTERVAL);
                }
            } catch (InterruptedException e) {
                throw new AssertionError(e);
            }
        }
    };
    test.setDaemon(true);
    test.start();
    localSet.await();
    assertEquals("hello", unsafeThreadLocal.get(test));
    assertEquals(null, unsafeThreadLocal.get(Thread.currentThread()));
}

