@Test
public void testReentrantLock() throws Exception {
    Assert.assertEquals(Scope.GLOBAL, region.getAttributes().getScope());
    final Lock lock1 = region.getDistributedLock(id);
    final Lock lock2 = region.getDistributedLock(id);
    for (int i = 0; i < 50; i++) {
        lock1.lock();
        boolean reenteredLock = false;
        try {
            reenteredLock = lock2.tryLock(1, TimeUnit.NANOSECONDS);
            if (!reenteredLock) {
                System.out.println("ERROR: could not reenter lock");
            }
            Assert.assertTrue("Failed getting lock at 2:" + i, reenteredLock);
        } finally {
            if (reenteredLock) {
                lock2.unlock();
            }
            lock1.unlock();
        }
    }
}

@Test
public void reentrantLockIncreasesReentrancy() {
    assertTrue(dLockService.lock("key1", -1, -1));
    DLockToken key1 = ((DLockService) dLockService).getToken("key1");
    assertEquals(0, key1.getRecursion());
    assertEquals(1, key1.getUsageCount());
    // reentrancy + 1
    assertTrue(dLockService.lock("key1", -1, -1));
    assertEquals(1, key1.getRecursion());
    assertEquals(2, key1.getUsageCount());
    dLockService.unlock("key1");
    assertEquals(0, key1.getRecursion());
    assertEquals(1, key1.getUsageCount());
    dLockService.unlock("key1");
    assertTokenIsUnused(key1);
}

@Test
public void threadWaitingOnLockIncreasesUsageCount() {
    assertTrue(dLockService.lock("key1", -1, -1));
    DLockToken key1 = ((DLockService) dLockService).getToken("key1");
    assertEquals(0, key1.getRecursion());
    assertEquals(1, key1.getUsageCount());
    assertEquals(Thread.currentThread(), key1.getThread());
    Thread otherThread = new Thread(() -> dLockService.lock("key1", -1, -1));
    otherThread.start();
    // otherThread should be waiting for lock.
    await("other thread is waiting on this lock").atMost(3, TimeUnit.SECONDS).until(() -> key1.getUsageCount() == 2);
    assertEquals(0, key1.getRecursion());
    assertEquals(Thread.currentThread(), key1.getThread());
    dLockService.unlock("key1");
    await("other thread has acquired this lock").atMost(3, TimeUnit.SECONDS).until(() -> key1.getThread() == otherThread);
    assertEquals(0, key1.getRecursion());
    assertEquals(1, key1.getUsageCount());
    // We can unlock from a different thread than locked it.
    dLockService.unlock("key1");
    assertTokenIsUnused(key1);
}

@Test
public void basicDLockUsage() throws InterruptedException, ExecutionException, TimeoutException {
    Lock lock = testRegion.getDistributedLock("testLockName");
    lock.lockInterruptibly();
    Future<Boolean> future = executorService.submit(() -> lock.tryLock());
    assertFalse("should not be able to get lock from another thread", future.get(5, TimeUnit.SECONDS));
    assertTrue("Lock is reentrant", lock.tryLock());
    // now locked twice.
    future = executorService.submit(() -> lock.tryLock());
    assertFalse("should not be able to get lock from another thread", future.get(5, TimeUnit.SECONDS));
    lock.unlock();
    future = executorService.submit(() -> lock.tryLock());
    assertFalse("should not be able to get lock from another thread", future.get());
    lock.unlock();
    future = executorService.submit(() -> {
        boolean locked = lock.tryLock();
        if (!locked) {
            return false;
        }
        lock.unlock();
        return true;
    });
    assertTrue("Another thread can now take out the lock", future.get(5, TimeUnit.SECONDS));
    DLockService lockService = (DLockService) testRegion.getLockService();
    Collection<DLockToken> tokens = lockService.getTokens();
    for (DLockToken token : tokens) {
        assertEquals(0, token.getUsageCount());
    }
}

