@Test
public void testConcurrency() throws Exception {
    CountDownLatch latch = new CountDownLatch(1);
    DelayHandler handler = new DelayHandler(latch);
    start(handler);
    final AtomicBoolean done = new AtomicBoolean();
    Thread delayedThread = new Thread() {

        public void run() {
            Boolean delay = Boolean.valueOf(true);
            try {
                new TcpClient().requestToServer(localhost, port, delay, 60 * 1000);
            } catch (IOException e) {
                e.printStackTrace();
            } catch (ClassNotFoundException e) {
                e.printStackTrace();
            }
            done.set(true);
        }
    };
    delayedThread.start();
    try {
        Thread.sleep(500);
        assertFalse(done.get());
        new TcpClient().requestToServer(localhost, port, Boolean.valueOf(false), 60 * 1000);
        assertFalse(done.get());
        latch.countDown();
        Thread.sleep(500);
        assertTrue(done.get());
    } finally {
        latch.countDown();
        delayedThread.join(60 * 1000);
        // GemStoneAddition
        assertTrue(!delayedThread.isAlive());
        try {
            new TcpClient().stop(localhost, port);
        } catch (ConnectException ignore) {
            // must not be running
        }
        server.join(60 * 1000);
    }
}

