                custMap.put(custId, customer);
                map.put(custId, customer);
            }
            custRegion.putAll(custMap);
            nonColocatedRegion.putAll(orderMap);
            mgr.rollback();
            assertEquals(15, custRegion.size());
            assertEquals(5, nonColocatedRegion.size());
            return null;
        }
    });
}

