public void testBug42728() throws InterruptedException, IOException {
    Region region = createRegion();
    putEntries(region, 0, 5, "A");
    putEntries(region, 0, 1, "B");
    invalidateEntries(region, 1, 2);
    removeEntries(region, 2, 3);
