        diskRegionProperties.setRolling(true);
        LocalRegion.ISSUE_CALLBACKS_TO_CACHE_OBSERVER = true;
        Region region = DiskRegionHelperFactory.getSyncPersistOnlyRegion(cache, diskRegionProperties, Scope.LOCAL);
        CacheObserverHolder.setInstance(new CacheObserverAdapter() {

            public void beforeGoingToCompact() {
                synchronized (forWaitNotify) {
                    forWaitNotify.notify();
                    gotNotification = true;
                }
            }
        });
        // This will end up 50% garbage
        // 1 live create
        // 2 live tombstones
        // 2 garbage creates and 1 garbage modify
        region.put("k1", "v1");
        region.put("k2", "v2");
        region.put("k2", "v3");
        region.put("k3", "v3");
        region.remove("k1");
        region.remove("k2");
        region.forceRolling();
        synchronized (forWaitNotify) {
            if (!gotNotification) {
                forWaitNotify.wait(10000);
            }
        }
        if (!gotNotification) {
            fail("Expected rolling to have happened but did not happen");
        }
    } catch (Exception e) {
        fail(" tests failed due to " + e);
    }
    LocalRegion.ISSUE_CALLBACKS_TO_CACHE_OBSERVER = false;
}

