 * i.e. before GII, P's RVVGC=P0,R0, upon received RequestImageMessage, it becomes P4,R0 it should
 * cause the fullGII.
 */
@Test
public void testFullGIITriggeredByHigherRVVGC() throws Throwable {
    prepareForEachTest();
