            attr.setPartitionAttributes(new PartitionAttributesFactory().setTotalNumBuckets(totalNumBuckets).create());
            Region p = cache.createRegion(r, attr.create());
            assertNotNull(p);
            assertTrue(!p.isDestroyed());
            assertNull(p.get("Key"));
