            Random rand = new Random(123);
            // Assert that its empty
            for (int i = 0; i < 5; i++) {
                LogWriterUtils.getLogWriter().info("Invocation " + i + " of getSomeKeys");
                try {
                    Set s = null;
                    s = pr.getSomeKeys(rand);
