            final int MAXKEYS = 50;
            for (int i = 0; i < MAXKEYS; i++) {
                pr.put("testKey" + i, new Integer(i));
            }
            // Assert not empty and has value in an accepable range
            for (int i = 0; i < 5; i++) {
                LogWriterUtils.getLogWriter().info("Invocation " + i + " of getSomeKeys");
