    // that VM1 has crashed.
    createPersistentRegion(vm2);
    updateTheEntry(vm1);
    closeRegion(vm1);
    closeRegion(vm2);
    // This ought to wait for VM1 to come back
    AsyncInvocation future = createPersistentRegionAsync(vm0);
