    t1.start();
    Thread t2 = new Thread(new Runnable() {

        public void run() {
            Awaitility.await().pollInterval(10, TimeUnit.MILLISECONDS).pollDelay(10, TimeUnit.MILLISECONDS).atMost(30, TimeUnit.SECONDS).until(() -> departedMember != null && processor.getSelectedNode() != null && departedMember != processor.getSelectedNode());
            // Handle search result from the departed member
            processor.incomingNetSearchReply(v1, System.currentTimeMillis(), false, false, true, mock(VersionTag.class), departedMember);
        }
    });
    t2.start();
    Thread t3 = new Thread(new Runnable() {

        public void run() {
            Awaitility.await().pollInterval(10, TimeUnit.MILLISECONDS).pollDelay(10, TimeUnit.MILLISECONDS).atMost(30, TimeUnit.SECONDS).until(() -> departedMember != null && processor.getSelectedNode() != null && departedMember != processor.getSelectedNode());
            // Handle search result from a new member
            processor.incomingNetSearchReply(v2, System.currentTimeMillis(), false, false, true, mock(VersionTag.class), processor.getSelectedNode());
        }
    });
    t3.start();
    processor.initialize(lr, key, null);
    processor.doSearchAndLoad(event, null, null);
    assertTrue(Arrays.equals((byte[]) event.getNewValue(), v2));
}

