                fail("Interrupted while registering", ex);
            }
        }
    };
    thread.start();
    try {
        DataSerializer.readObject(getDataInput());
    } finally {
        try {
            long ms = 30 * 1000;
            thread.join(ms);
            if (thread.isAlive()) {
                thread.interrupt();
                fail("Thread did not terminate after " + ms + " ms: " + thread);
