 * SQLException.
 */
@Test
public void testScenario9() throws Exception {
    this.tblIDFld = 9;
    this.tblNameFld = "test9";
    boolean rollback_chances = true;
    int first_field = this.tblIDFld;
    JTAUtils jtaObj = new JTAUtils(cache, currRegion);
