/**
 * Test populates an offheap heaplru persistent region that contains more data than can fit in
 * offheap memory. It then recovers the region to demonstrate that recovering this data will not
 * try to put everything into offheap but instead leave some of it on disk.
 */
@Test
public void recoveringTooMuchDataDoesNotRunOutOfOffHeapMemory() {
    final int ENTRY_COUNT = 40;
    GemFireCacheImpl gfc = createCache();
    try {
        Region<Object, Object> r = createRegion(gfc);
        byte[] v = new byte[1024 * 1024];
        for (int i = 0; i < ENTRY_COUNT; i++) {
            r.put(i, v);
        }
    } finally {
        closeCache(gfc);
    }
    Awaitility.await().atMost(60, TimeUnit.SECONDS).until(() -> {
        return MemoryAllocatorImpl.getAllocator().getStats().getObjects() == 0;
    });
    System.setProperty("gemfire.disk.recoverValuesSync", "true");
    System.setProperty("gemfire.disk.recoverLruValues", "true");
    try {
        gfc = createCache();
        try {
            createDiskStore(gfc);
            try {
                int offHeapObjects = MemoryAllocatorImpl.getAllocator().getStats().getObjects();
                if (offHeapObjects < 10) {
                    fail("expected at least 10 offheap values to be recovered but only did " + offHeapObjects);
                }
                if (offHeapObjects == ENTRY_COUNT) {
                    // Why "== ENTRY_COUNT" instead of "== 10"?
                    // As we recover values we asynchronously notify the resource manager
                    // of how much off-heap memory was consumed. Once it sees we are over
                    // the LRU limit then recovery of values will stop happening.
                    // Since it is async it can allow us to exceed the LRU limit.
                    // So far this test usually sees 10 but sometimes sees 11.
                    // I allow up to ENTRY_COUNT-1 just to prevent intermittent test failures.
                    // We should consider changing this async notification to be sync so
                    // that the limit can not be exceeded.
                    fail("expected at most " + (ENTRY_COUNT - 1) + " offheap values to be recovered but actually did " + offHeapObjects);
                }
            } finally {
                DiskStore ds = gfc.findDiskStore(DS_NAME);
                ds.destroy();
            }
        } finally {
            closeCache(gfc);
        }
    } finally {
        System.clearProperty("gemfire.disk.recoverValuesSync");
        System.clearProperty("gemfire.disk.recoverLruValues");
    }
}

@Test
public void testSizeAllocation() {
    // prevent cache from closing in reaction to ooom
    System.setProperty(OffHeapStorage.STAY_CONNECTED_ON_OUTOFOFFHEAPMEMORY_PROPERTY, "true");
    GemFireCacheImpl gfc = createCache();
    try {
        MemoryAllocator ma = gfc.getOffHeapStore();
        assertNotNull(ma);
        final long offHeapSize = ma.getFreeMemory();
        assertEquals(0, ma.getUsedMemory());
        StoredObject mc1 = ma.allocate(64);
        assertEquals(64 + perObjectOverhead(), ma.getUsedMemory());
        assertEquals(offHeapSize - (64 + perObjectOverhead()), ma.getFreeMemory());
        mc1.release();
        assertEquals(offHeapSize, ma.getFreeMemory());
        assertEquals(0, ma.getUsedMemory());
        // do an allocation larger than the slab size
        // TODO: currently the defragment will produce slabs bigger than the max slab size
        // (see the todo comment on defragment() in FreeListManager).
        // So we request 20m here since that it the total size.
        try {
            ma.allocate(1024 * 1024 * 20);
            fail("Expected an out of heap exception");
        } catch (OutOfOffHeapMemoryException expected) {
        }
        assertEquals(0, ma.getUsedMemory());
        assertFalse(gfc.isClosed());
    } finally {
        System.clearProperty(OffHeapStorage.STAY_CONNECTED_ON_OUTOFOFFHEAPMEMORY_PROPERTY);
        closeCache(gfc, false);
    }
}

@Test
public void testByteArrayAllocation() {
    GemFireCacheImpl gfc = createCache();
    try {
        MemoryAllocator ma = gfc.getOffHeapStore();
        assertNotNull(ma);
        final long offHeapSize = ma.getFreeMemory();
        assertEquals(0, ma.getUsedMemory());
        byte[] data = new byte[] { 1, 2, 3, 4, 5, 6, 7, 8 };
        StoredObject mc1 = (StoredObject) ma.allocateAndInitialize(data, false, false);
        assertEquals(data.length + perObjectOverhead(), ma.getUsedMemory());
        assertEquals(offHeapSize - (data.length + perObjectOverhead()), ma.getFreeMemory());
        byte[] data2 = new byte[data.length];
        mc1.readDataBytes(0, data2);
        assertTrue(Arrays.equals(data, data2));
        mc1.release();
        assertEquals(offHeapSize, ma.getFreeMemory());
        assertEquals(0, ma.getUsedMemory());
        // try some small byte[] that don't need to be stored off heap.
        data = new byte[] { 1, 2, 3, 4, 5, 6, 7 };
        StoredObject so1 = ma.allocateAndInitialize(data, false, false);
        assertEquals(0, ma.getUsedMemory());
        assertEquals(offHeapSize, ma.getFreeMemory());
        data2 = new byte[data.length];
        data2 = (byte[]) so1.getDeserializedForReading();
        assertTrue(Arrays.equals(data, data2));
    } finally {
        closeCache(gfc, false);
    }
}

