            } catch (InterruptedException e) {
                fail("interrupted");
            }
            return Boolean.TRUE;
        }
    });
    assertTrue("Task did not complete", ((Boolean) f.get()).booleanValue());
    assertEquals(2, ex.getLargestPoolSize());
}

