@Test
public void testDestroyDistributedRegion() {
    MemberVM.invokeInEveryMember(() -> {
        Cache cache = LocatorServerStartupRule.serverStarter.getCache();
        RegionFactory<Object, Object> factory = cache.createRegionFactory(RegionShortcut.PARTITION);
        factory.create("Customer");
        PartitionAttributesFactory paFactory = new PartitionAttributesFactory();
        paFactory.setColocatedWith("Customer");
        factory.setPartitionAttributes(paFactory.create());
        factory.create("Order");
    }, server1, server2);
    locator.invoke(() -> waitForRegionMBeanCreation("/Customer", 2));
    locator.invoke(() -> waitForRegionMBeanCreation("/Order", 2));
    // Test unable to destroy with co-location
    gfsh.executeAndAssertThat("destroy region --name=/Customer").statusIsError().containsOutput("The parent region [/Customer] in colocation chain cannot be destroyed");
    // Test success
    gfsh.executeAndAssertThat("destroy region --name=/Order").statusIsSuccess().containsOutput("destroyed successfully");
    gfsh.executeAndAssertThat("destroy region --name=/Customer").statusIsSuccess().containsOutput("destroyed successfully");
    // destroy something that's not exist anymore
    gfsh.executeAndAssertThat("destroy region --name=/Customer").statusIsError().containsOutput("Could not find a Region");
    gfsh.executeAndAssertThat("destroy region --name=/Customer --if-exists").statusIsSuccess();
}

