@Test
public void testHeadlessGfshTest() throws InterruptedException {
    for (int i = 0; i < 5; i++) {
        gfsh.executeCommand("connect --jmx-manager=localhost[" + port + "]");
        Object result = gfsh.getResult();
        assertTrue(gfsh.isConnectedAndReady());
        assertNotNull(result);
        gfsh.clear();
        gfsh.executeCommand("list members");
        result = gfsh.getResult();
        assertNotNull(result);
        gfsh.executeCommand("disconnect");
        gfsh.getResult();
    }
    long l1 = System.currentTimeMillis();
    gfsh.executeCommand("exit");
    long l2 = System.currentTimeMillis();
    gfsh.getResult();
    long l3 = System.currentTimeMillis();
    System.out.println("L3-l2=" + (l3 - l2) + " Total time= " + (l3 - l1) / 1000);
}

@Test
public void testStringResultReturnedAsCommandResult() throws InterruptedException {
    gfsh.clear();
    gfsh.executeCommand("list members");
    LinkedBlockingQueue headlessQueue = gfsh.getQueue();
    headlessQueue.clear();
    headlessQueue.put("ERROR RESULT");
    Object result = gfsh.getResult();
    assertNotNull(result);
    assertTrue(((CommandResult) result).getStatus() == Result.Status.ERROR);
    System.out.println(((CommandResult) result).toString());
}

@Test
public void testChildLevel() {
    HelpBlock block = new HelpBlock();
    assertThat(block.getLevel()).isEqualTo(-1);
    firstBlock.addChild(secondBlock);
    assertThat(firstBlock.getLevel()).isEqualTo(0);
    assertThat(secondBlock.getLevel()).isEqualTo(1);
    secondBlock.addChild(thirdBlock);
    assertThat(firstBlock.getLevel()).isEqualTo(0);
    assertThat(secondBlock.getLevel()).isEqualTo(1);
    assertThat(thirdBlock.getLevel()).isEqualTo(2);
    assertThat(firstBlock.getChildren()).contains(secondBlock);
    assertThat(firstBlock.getChildren().size()).isEqualTo(1);
    assertThat(secondBlock.getChildren()).contains(thirdBlock);
    assertThat(secondBlock.getChildren().size()).isEqualTo(1);
    // after manually set the level of the first block
    firstBlock.setLevel(10);
    assertThat(firstBlock.getLevel()).isEqualTo(10);
    assertThat(firstBlock.getData()).isEqualTo("First Line");
    assertThat(secondBlock.getLevel()).isEqualTo(11);
    assertThat(secondBlock.getData()).isEqualTo("Second Line");
    assertThat(thirdBlock.getLevel()).isEqualTo(12);
    assertThat(thirdBlock.getData()).isEqualTo("Third Line");
}

@Test
public void testToString() {
    firstBlock.addChild(secondBlock);
    secondBlock.addChild(thirdBlock);
    StringBuilder expected = new StringBuilder();
    expected.append("First Line").append(GfshParser.LINE_SEPARATOR);
    expected.append("Second Line").append(GfshParser.LINE_SEPARATOR);
    expected.append("Third Line").append(GfshParser.LINE_SEPARATOR);
    String result = firstBlock.toString(-1);
    assertThat(result).isEqualTo(expected.toString());
}

