    // Take off last element one at a time
    for (int i = elements - 1; i >= 0; i--) {
        jedis.ltrim(key, 0, i);
        List<String> range = jedis.lrange(key, 0, -1);
        assertEquals(range, strings.subList(0, i + 1));
