    // wait for all creates to arrive.
    for (int i = 1; i <= 5; i++) {
        cqDUnitTest.waitForCreated(client, name, CqQueryUsingPoolDUnitTest.KEY + i);
    }
    // do more puts to push first five key-value to disk.
