    cqDUnitTest.createValues(server1, cqDUnitTest.regions[1], 10);
    for (int i = 1; i <= 10; i++) {
        cqDUnitTest.waitForCreated(client1, "testMatchingCQsWithMultipleServers_0", CqQueryDUnitTest.KEY + i);
    }
    Wait.pause(1 * 1000);
    cqDUnitTest.createServer(server2, ports[0]);
    final int port2 = server2.invoke(() -> CqQueryDUnitTest.getCacheServerPort());
    System.out.println("### Port on which server1 running : " + port1 + " Server2 running : " + port2);
    Wait.pause(3 * 1000);
    // UPDATE - 1.
    for (int k = 0; k < numCQs; k++) {
        cqDUnitTest.clearCQListenerEvents(client1, "testMatchingCQsWithMultipleServers_" + k);
        cqDUnitTest.clearCQListenerEvents(client2, "testMatchingCQsWithMultipleServers_" + k);
    }
    cqDUnitTest.createValues(server1, cqDUnitTest.regions[0], 10);
    cqDUnitTest.createValues(server1, cqDUnitTest.regions[1], 10);
    // Wait for updates on regions[0]
    for (int i = 1; i <= 10; i++) {
        cqDUnitTest.waitForUpdated(client1, "testMatchingCQsWithMultipleServers_0", CqQueryDUnitTest.KEY + i);
        cqDUnitTest.waitForUpdated(client2, "testMatchingCQsWithMultipleServers_0", CqQueryDUnitTest.KEY + i);
    }
    // Wait for updates on regions[1] - Waiting for last key is good enough.
    cqDUnitTest.waitForUpdated(client1, "testMatchingCQsWithMultipleServers_2", CqQueryDUnitTest.KEY + 4);
    cqDUnitTest.waitForUpdated(client2, "testMatchingCQsWithMultipleServers_2", CqQueryDUnitTest.KEY + 4);
    int[] resultsCnt = new int[] { 10, 1, 2 };
    for (int i = 0; i < numCQs; i++) {
        cqDUnitTest.validateCQ(client1, "testMatchingCQsWithMultipleServers_" + i, CqQueryDUnitTest.noTest, resultsCnt[i], resultsCnt[i], CqQueryDUnitTest.noTest);
        cqDUnitTest.validateCQ(client2, "testMatchingCQsWithMultipleServers_" + i, CqQueryDUnitTest.noTest, resultsCnt[i], resultsCnt[i], CqQueryDUnitTest.noTest);
    }
    // Close server1.
    cqDUnitTest.closeServer(server1);
    // Fail over should happen.
    Wait.pause(5 * 1000);
    validateMatchingCqs(server2, numCQs, cqDUnitTest.cqs[0], 1 * clients.length);
    for (int i = 0; i < numCQs; i++) {
        cqDUnitTest.validateCQ(client1, "testMatchingCQsWithMultipleServers_" + i, CqQueryDUnitTest.noTest, resultsCnt[i], resultsCnt[i], CqQueryDUnitTest.noTest);
        cqDUnitTest.validateCQ(client2, "testMatchingCQsWithMultipleServers_" + i, CqQueryDUnitTest.noTest, resultsCnt[i], resultsCnt[i], CqQueryDUnitTest.noTest);
    }
    // UPDATE - 2
    for (int k = 0; k < numCQs; k++) {
        cqDUnitTest.clearCQListenerEvents(client1, "testMatchingCQsWithMultipleServers_" + k);
        cqDUnitTest.clearCQListenerEvents(client2, "testMatchingCQsWithMultipleServers_" + k);
    }
    cqDUnitTest.createValues(server2, cqDUnitTest.regions[0], 10);
    cqDUnitTest.createValues(server2, cqDUnitTest.regions[1], 10);
    // Wait for cq1. on region[0]
    for (int i = 1; i <= resultsCnt[0]; i++) {
        cqDUnitTest.waitForUpdated(client1, "testMatchingCQsWithMultipleServers_0", CqQueryDUnitTest.KEY + i);
        cqDUnitTest.waitForUpdated(client2, "testMatchingCQsWithMultipleServers_0", CqQueryDUnitTest.KEY + i);
    }
    // Wait for cq3. on region[1]
    {
        cqDUnitTest.waitForUpdated(client1, "testMatchingCQsWithMultipleServers_2", CqQueryDUnitTest.KEY + "4");
        cqDUnitTest.waitForUpdated(client2, "testMatchingCQsWithMultipleServers_2", CqQueryDUnitTest.KEY + "4");
    }
    for (int i = 0; i < numCQs; i++) {
        cqDUnitTest.validateCQ(client1, "testMatchingCQsWithMultipleServers_" + i, CqQueryDUnitTest.noTest, resultsCnt[i], resultsCnt[i] * 2, CqQueryDUnitTest.noTest);
        cqDUnitTest.validateCQ(client2, "testMatchingCQsWithMultipleServers_" + i, CqQueryDUnitTest.noTest, resultsCnt[i], resultsCnt[i] * 2, CqQueryDUnitTest.noTest);
    }
    // Close.
    cqDUnitTest.closeClient(client1);
    validateMatchingCqs(server2, numCQs, cqDUnitTest.cqs[0], 1 * (clients.length - 1));
    cqDUnitTest.closeClient(client2);
    cqDUnitTest.closeServer(server2);
}

