    cqDUnitTest.createValues(server2, cqDUnitTest.regions[1], 10);
    // Wait for cq1. on region[0]
    for (int i = 1; i <= resultsCnt[0]; i++) {
        cqDUnitTest.waitForUpdated(client1, "testMatchingCQsWithMultipleServers_0", CqQueryUsingPoolDUnitTest.KEY + i);
        cqDUnitTest.waitForUpdated(client2, "testMatchingCQsWithMultipleServers_0", CqQueryUsingPoolDUnitTest.KEY + i);
    }
    // Wait for cq3. on region[1]
    {
        cqDUnitTest.waitForUpdated(client1, "testMatchingCQsWithMultipleServers_2", CqQueryUsingPoolDUnitTest.KEY + "4");
        cqDUnitTest.waitForUpdated(client2, "testMatchingCQsWithMultipleServers_2", CqQueryUsingPoolDUnitTest.KEY + "4");
