@Test
public void extractsClassNames() throws Exception {
    SoftAssertions softAssertions = new SoftAssertions();
    ClassNameExtractor classNameExtractor = new ClassNameExtractor();
    Set<List<String>> permutationsToTest = Sets.cartesianProduct(ImmutableSet.of("public ", "private ", "protected ", ""), ImmutableSet.of("abstract ", ""), ImmutableSet.of("static ", ""), ImmutableSet.of("class ", "interface "), ImmutableSet.of("extends Foo ", ""), ImmutableSet.of("implements Bar ", ""));
    for (List<String> permutation : permutationsToTest) {
        String firstLineOfSource = permutation.get(0) + permutation.get(1) + permutation.get(2) + permutation.get(3) + CLASS_NAME_TO_FIND + SPACE + permutation.get(4) + permutation.get(5) + " {";
        String className = classNameExtractor.extractFromSourceCode(firstLineOfSource);
        softAssertions.assertThat(className).isEqualTo(CLASS_NAME_TO_FIND);
    }
    softAssertions.assertAll();
}

