@Test
public void verifyMemberWithGroupStartsAfterAlterRegion() throws Exception {
    // Start a member with no group
    ls.startServerVM(1, locator.getPort());
    // Start a member with group
    String group = "group1";
    Properties properties = new Properties();
    properties.setProperty(GROUPS, group);
    MemberVM vm2 = ls.startServerVM(2, properties, locator.getPort());
    // Connect Gfsh to locator
    gfshConnector.connectAndVerify(locator);
    // Create index and region in no group
    createLuceneIndexUsingGfsh();
    createRegionUsingGfsh(REGION_NAME, RegionShortcut.PARTITION, null);
    // Alter region in group
    CommandStringBuilder csb = new CommandStringBuilder(CliStrings.ALTER_REGION);
    csb.addOption(CliStrings.ALTER_REGION__REGION, REGION_NAME);
    csb.addOption(CliStrings.GROUP, group);
    csb.addOption(CliStrings.ALTER_REGION__EVICTIONMAX, "5764");
    String expectedStatusOutput = "Region \"/" + REGION_NAME + "\" altered on \"" + vm2.getName() + "\"";
    gfshConnector.executeAndAssertThat(csb.toString()).statusIsSuccess().tableHasColumnWithExactValuesInExactOrder("Status", expectedStatusOutput);
    // Start another member with group
    ls.startServerVM(3, properties, locator.getPort());
    // Verify all members have indexes
    csb = new CommandStringBuilder(LuceneCliStrings.LUCENE_LIST_INDEX);
    gfshConnector.executeAndAssertThat(csb.toString()).statusIsSuccess().tableHasColumnWithExactValuesInExactOrder("Status", "Initialized", "Initialized", "Initialized");
}

@Test
public void shouldDumpReadableLuceneIndexFile() throws Exception {
    luceneService.createIndexFactory().setFields("title", "description").create(INDEX_NAME, REGION_NAME);
    Region region = createRegion(REGION_NAME, RegionShortcut.PARTITION);
    region.put(0, new TestObject("title 1", "hello world"));
    region.put(1 * 113, new TestObject("title 2", "this will not match"));
    region.put(2 * 113, new TestObject("title 3", "hello world"));
    region.put(3 * 113, new TestObject("hello world", "hello world"));
    InternalLuceneIndex index = (InternalLuceneIndex) luceneService.getIndex(INDEX_NAME, REGION_NAME);
    luceneService.waitUntilFlushed(INDEX_NAME, REGION_NAME, 60000, TimeUnit.MILLISECONDS);
    index.dumpFiles(tempFolderRule.getRoot().getAbsolutePath());
    // Find the directory for the first bucket
    File bucket0 = tempFolderRule.getRoot().listFiles(file -> file.getName().endsWith("_0"))[0];
    // Test that we can read the lucene index from the dump
    final FSDirectory directory = FSDirectory.open(bucket0.toPath());
    IndexReader reader = DirectoryReader.open(directory);
    IndexSearcher searcher = new IndexSearcher(reader);
    final TopDocs results = searcher.search(new MatchAllDocsQuery(), 1000);
    assertEquals(4, results.totalHits);
}

