        putSerializableObjectAndVerifyLuceneQueryResult(server2, regionName, expectedRegionSize, 15, 25, server1, server2);
        expectedRegionSize += 5;
        putSerializableObjectAndVerifyLuceneQueryResult(server1, regionName, expectedRegionSize, 20, 30, server1, server2);
        server2 = rollServerToCurrentAndCreateRegion(server2, regionType, null, shortcut.name(), regionName, locatorPorts);
