        putSerializableObjectAndVerifyLuceneQueryResult(server1, regionName, expectedRegionSize, 30, 40, server1, server2);
    } finally {
        invokeRunnableInVMs(true, invokeStopLocator(), locator1, locator2);
        invokeRunnableInVMs(true, invokeCloseCache(), server1, server2);
    }
}

@Test
public void luceneQueryReturnsCorrectResultsAfterClientAndServersAreRolledOver() throws Exception {
    final Host host = Host.getHost(0);
    VM locator = host.getVM(oldVersion, 0);
    VM server2 = host.getVM(oldVersion, 1);
    VM server3 = host.getVM(oldVersion, 2);
    VM client = host.getVM(oldVersion, 3);
    final String regionName = "aRegion";
    String regionType = "partitionedRedundant";
    RegionShortcut shortcut = RegionShortcut.PARTITION_REDUNDANT;
    int[] ports = AvailablePortHelper.getRandomAvailableTCPPorts(3);
    int[] locatorPorts = new int[] { ports[0] };
    int[] csPorts = new int[] { ports[1], ports[2] };
    DistributedTestUtils.deleteLocatorStateFile(locatorPorts);
    String hostName = NetworkUtils.getServerHostName(host);
    String[] hostNames = new String[] { hostName };
    String locatorString = getLocatorString(locatorPorts);
    try {
        locator.invoke(invokeStartLocator(hostName, locatorPorts[0], getLocatorPropertiesPre91(locatorString)));
        invokeRunnableInVMs(invokeCreateCache(getSystemProperties(locatorPorts)), server2, server3);
        invokeRunnableInVMs(invokeStartCacheServer(csPorts[0]), server2);
        invokeRunnableInVMs(invokeStartCacheServer(csPorts[1]), server3);
        invokeRunnableInVMs(invokeCreateClientCache(getClientSystemProperties(), hostNames, locatorPorts, false), client);
        server2.invoke(() -> createLuceneIndex(cache, regionName, INDEX_NAME));
        server3.invoke(() -> createLuceneIndex(cache, regionName, INDEX_NAME));
        invokeRunnableInVMs(invokeCreateRegion(regionName, shortcut.name()), server2, server3);
        invokeRunnableInVMs(invokeCreateClientRegion(regionName, ClientRegionShortcut.PROXY), client);
        int expectedRegionSize = 10;
        putSerializableObjectAndVerifyLuceneQueryResult(client, regionName, expectedRegionSize, 0, 10, server3);
        expectedRegionSize += 10;
        putSerializableObjectAndVerifyLuceneQueryResult(server3, regionName, expectedRegionSize, 10, 20, server2);
        locator = rollLocatorToCurrent(locator, hostName, locatorPorts[0], getTestMethodName(), locatorString);
        server3 = rollServerToCurrentAndCreateRegion(server3, regionType, null, shortcut.name(), regionName, locatorPorts);
        invokeRunnableInVMs(invokeStartCacheServer(csPorts[1]), server3);
        expectedRegionSize += 10;
        putSerializableObjectAndVerifyLuceneQueryResult(client, regionName, expectedRegionSize, 20, 30, server3, server2);
        expectedRegionSize += 10;
        putSerializableObjectAndVerifyLuceneQueryResult(server3, regionName, expectedRegionSize, 30, 40, server2);
        server2 = rollServerToCurrentAndCreateRegion(server2, regionType, null, shortcut.name(), regionName, locatorPorts);
        invokeRunnableInVMs(invokeStartCacheServer(csPorts[0]), server2);
        expectedRegionSize += 10;
        putSerializableObjectAndVerifyLuceneQueryResult(client, regionName, expectedRegionSize, 40, 50, server2, server3);
        expectedRegionSize += 10;
        putSerializableObjectAndVerifyLuceneQueryResult(server2, regionName, expectedRegionSize, 50, 60, server3);
        client = rollClientToCurrentAndCreateRegion(client, ClientRegionShortcut.PROXY, regionName, hostNames, locatorPorts, false);
        expectedRegionSize += 10;
        putSerializableObjectAndVerifyLuceneQueryResult(client, regionName, expectedRegionSize, 60, 70, server2, server3);
        expectedRegionSize += 10;
        putSerializableObjectAndVerifyLuceneQueryResult(server2, regionName, expectedRegionSize, 70, 80, server3);
    } finally {
        invokeRunnableInVMs(true, invokeStopLocator(), locator);
        invokeRunnableInVMs(true, invokeCloseCache(), server2, server3, client);
    }
}

