public // This test verifies that a GatewaySenderProfile serializes properly between versions.
void testVerifyGatewaySenderProfile() throws Exception {
    final Host host = Host.getHost(0);
    VM oldLocator = host.getVM(oldVersion, 0);
    VM oldServer = host.getVM(oldVersion, 1);
    VM currentServer = host.getVM(2);
    // Start locator
    final int port = AvailablePort.getRandomAvailablePort(AvailablePort.SOCKET);
    DistributedTestUtils.deleteLocatorStateFile(port);
    final String locators = NetworkUtils.getServerHostName(host) + "[" + port + "]";
    oldLocator.invoke(() -> startLocator(port, 0, locators, ""));
    IgnoredException ie = IgnoredException.addIgnoredException("could not get remote locator information");
    try {
        // Start old server
        oldServer.invoke(() -> createCache(locators));
        // Create GatewaySender in old server
        String senderId = getName() + "_gatewaysender";
        oldServer.invoke(() -> createGatewaySender(senderId, 10, ParallelGatewaySenderQueue.DEFAULT_MESSAGE_SYNC_INTERVAL));
