        // Attempt to create GatewaySender in new server
        currentServer.invoke(() -> createGatewaySender(senderId, 10, ParallelGatewaySenderQueue.DEFAULT_MESSAGE_SYNC_INTERVAL));
    } finally {
        ie.remove();
    }
}

