    gfsh.executeAndAssertThat("export config --group=Group2 --dir=" + tempDir.getAbsolutePath()).statusIsSuccess();
    expectedFiles = Arrays.asList("server-1-cache.xml", "server-2-cache.xml", "server-1-gf.properties", "server-2-gf.properties");
    actualFiles = Arrays.stream(tempDir.listFiles()).map(File::getName).collect(Collectors.toList());
    assertThat(actualFiles).hasSameElementsAs(expectedFiles);
    tempDir.delete();
}

